func htGolden(emonT *testing.T, mfile string, hfile string, opts int32, below int32) int32 {
	// Build the Model `mfile`, emit it under `opts`, and require the
	// bytes of the golden `hfile`.
	var nodes *port.Cells = port.NewCells()
	var attrs *port.Cells = port.NewCells()
	var regions *port.Cells = port.NewCells()
	var text *port.Cells = port.NewCells()
	var pages *port.Cells = port.NewCells()
	var ledger *port.Cells = port.NewCells()
	var layout *port.Cells = port.NewCells()
	var st *port.Cells = port.NewCells()
	var out *strings.Builder = port.NewText()
	port.AssertEq(emonT, mscript.JtBuild(port.TestFile(mfile), nodes, attrs, regions, text, pages, ledger, layout, st), 0, "the script builds")
	port.AssertEq(emonT, model.ModelCheck(nodes, attrs, regions, text, pages, ledger, layout, st), 0, "the Model is well formed")
	port.AssertEq(emonT, html.HtmlEmit(out, opts, below, nodes, attrs, regions, text, pages, ledger, layout, port.NewCells(), port.NewCells(), port.NewBuf(), port.NewCells()), 0, "it emits")
	port.AssertTextSpan(emonT, out, port.TestFile(hfile), 0, mscript.JtEnd(port.TestFile(hfile)), "the golden", 0)
	return 0
}

func htSet(nodes *port.Cells, text *port.Cells, n int32, b []byte) int32 {
	// Give node n the UTF-8 bytes of b as its text.
	var start int32 = model.TextLen(text)
	model.TextAppendUtf8(text, b, 0, port.BlobLen(b))
	model.NodeSetText(nodes, n, start, model.TextLen(text)-start)
	return 0
}

